-- A10 - COMPLETE LOAD
-- Quality Management (Inspection Lot per Goods Receipt item + Usage Decision)
-- ============================================================================

-- FASE 1: DROP (cascade) - tabelas novas, esperado erro 'table not found' na 1a execucao, usar Skip All
DROP TABLE INDUSTRIAL_DATA.INSPECTION_LOT CASCADE;
DROP TABLE INDUSTRIAL_DATA.UD_CODE CASCADE;
DROP TABLE INDUSTRIAL_DATA.INSPECTION_TYPE CASCADE;

-- FASE 2: CREATE CONFIG TABLES
CREATE TABLE INDUSTRIAL_DATA.INSPECTION_TYPE (INSPECTION_TYPE_CODE NVARCHAR(2) NOT NULL PRIMARY KEY, INSPECTION_TYPE_TEXT NVARCHAR(60) NOT NULL);
CREATE TABLE INDUSTRIAL_DATA.UD_CODE (UD_CODE NVARCHAR(10) NOT NULL PRIMARY KEY, UD_TEXT NVARCHAR(60) NOT NULL);

-- FASE 3: LOAD CONFIG DATA


-- FASE 4: CREATE INSPECTION LOT
CREATE TABLE INDUSTRIAL_DATA.INSPECTION_LOT (
  LOT_ID NVARCHAR(12) NOT NULL PRIMARY KEY,
  GR_ID NVARCHAR(10) NOT NULL,
  MATNR NVARCHAR(10) NOT NULL,
  WERKS NVARCHAR(4) NOT NULL,
  INSPECTION_TYPE_CODE NVARCHAR(2) NOT NULL,
  LOT_QUANTITY DECIMAL(15, 2) NOT NULL,
  UD_CODE NVARCHAR(10) NOT NULL,
  CREATED_DATE DATE NOT NULL,
  UD_DATE DATE,
  FOREIGN KEY (GR_ID) REFERENCES INDUSTRIAL_DATA.GOODS_RECEIPT(GR_ID),
  FOREIGN KEY (MATNR) REFERENCES INDUSTRIAL_DATA.MATERIAL(MATNR),
  FOREIGN KEY (WERKS) REFERENCES INDUSTRIAL_DATA.PLANT(WERKS),
  FOREIGN KEY (INSPECTION_TYPE_CODE) REFERENCES INDUSTRIAL_DATA.INSPECTION_TYPE(INSPECTION_TYPE_CODE),
  FOREIGN KEY (UD_CODE) REFERENCES INDUSTRIAL_DATA.UD_CODE(UD_CODE),
  CHECK (LOT_QUANTITY >= 0)
);

