SELECT 'A10 LOADED SUCCESSFULLY' FROM DUMMY;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.INSPECTION_TYPE;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.UD_CODE;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.INSPECTION_LOT;
SELECT UD_CODE, COUNT(*) FROM INDUSTRIAL_DATA.INSPECTION_LOT GROUP BY UD_CODE ORDER BY UD_CODE;
SELECT TOP 5 LOT_ID, GR_ID, MATNR, LOT_QUANTITY, UD_CODE FROM INDUSTRIAL_DATA.INSPECTION_LOT ORDER BY LOT_ID;
